package router

type Route struct {
	Prefix  string
	Handler string
	Enabled bool
}

// Resolve returns the handler for the most specific enabled prefix.
func Resolve(routes []Route, path string) (string, bool) {
	var bestHandler string
	var bestLen int = -1

	for _, route := range routes {
		if !route.Enabled {
			continue
		}

		if len(path) >= len(route.Prefix) && path[:len(route.Prefix)] == route.Prefix {
			if len(route.Prefix) > bestLen {
				bestLen = len(route.Prefix)
				bestHandler = route.Handler
			}
		}
	}

	if bestLen != -1 {
		return bestHandler, true
	}
	return "", false
}

package retry

import "errors"

type Store interface {
	Get(key string) (string, error)
	Put(key, value string) error
}

var ErrTemporary = errors.New("temporary")
var ErrMissing = errors.New("missing")

// Ensure reads key and writes fallback only when the key is missing.
func Ensure(store Store, key, fallback string) (string, error) {
	value, err := store.Get(key)
	if err == nil {
		return value, nil
	}

	if !errors.Is(err, ErrMissing) {
		return "", err
	}

	if err := store.Put(key, fallback); err != nil {
		return "", err
	}

	return fallback, nil
}

using System;
using System.Collections.Generic;
using System.Linq;

public static class Ledger
{
    // Returns, for each account, the running balance after every entry, and the
    // final balance. Entries are (account, delta) in chronological order.
    // BUG: callers report that the running balances are all identical to the
    // final balance, and that AverageDelta is truncated to a whole number.
    public static (Dictionary<string, List<int>> Running, Dictionary<string, int> Final, double AverageDelta)
        Summarise(IEnumerable<(string Account, int Delta)> entries)
    {
        var totals = new Dictionary<string, int>();
        var running = new Dictionary<string, List<int>>();

        foreach (var e in entries)
        {
            if (!totals.ContainsKey(e.Account)) 
            { 
                totals[e.Account] = 0; 
                running[e.Account] = new List<int>(); 
            }
            totals[e.Account] += e.Delta;
            running[e.Account].Add(totals[e.Account]);
        }

        var deltas = entries.Select(e => e.Delta).ToList();
        double average = 0;
        if (deltas.Count > 0)
        {
            average = (double)deltas.Sum() / deltas.Count;
        }

        return (running, totals, average);
    }
}

export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
      const seen = new Set<string>();
      const chain: string[] = [];
      let currentId: string | null = start;

      while (currentId !== null) {
        const id = currentId as string;
        if (seen.has(id)) {
          throw new Error("cycle detected");
        }
        seen.add(id);
        chain.push(id);

        if (chain.length > 50) {
          throw new Error("chain too long");
        }

        const node = await fetch(id);
        currentId = node.parent;
      }

      return chain;
    }

public static class FrameUtil
